import * as React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./AnchorNav.stories";
import AnchorNav, { AnchorNavList, AnchorNavListItem } from ".";

const { Basic } = composeStories(stories) as any;

describe("AnchorNav component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(
      <AnchorNav data-testid="anchornav">
        <AnchorNavList>
          <AnchorNavListItem href="#overview">Overview</AnchorNavListItem>
          <AnchorNavListItem href="#anatomy">Anatomy</AnchorNavListItem>
          <AnchorNavListItem href="#related">Related</AnchorNavListItem>
        </AnchorNavList>
      </AnchorNav>
    );
    expect(screen.getByTestId("anchornav")).toBeTruthy();
  });

  it("calls onSelected function correctly", () => {
    const mockSelected = jest.fn();
    render(
      <AnchorNav>
        <AnchorNavList>
          <AnchorNavListItem selected={true} onSelected={mockSelected}>
            Overview
          </AnchorNavListItem>
          <AnchorNavListItem selected={false} onSelected={mockSelected}>
            Anatomy
          </AnchorNavListItem>
          <AnchorNavListItem selected={false} onSelected={mockSelected}>
            Related
          </AnchorNavListItem>
        </AnchorNavList>
      </AnchorNav>
    );

    let link = screen.getByText("Related");
    fireEvent.click(link);
    expect(mockSelected).toHaveBeenCalledTimes(1);
  });
});
